"use client";

import { Flex } from "@chakra-ui/react"
import { DecorativeBox } from "@/components/rendyn-libraries/chakra/upstream/lib/decorative-box"

export const FlexBasic = () => {
  return (
    <Flex gap="4">
      <DecorativeBox height="10" />
      <DecorativeBox height="10" />
      <DecorativeBox height="10" />
    </Flex>
  )
}

"use client";

import { Box, type BoxProps } from "@chakra-ui/react"

export const DecorativeBox = (props: BoxProps) => (
  <Box
    {...props}
    css={{
      width: "100%",
      height: "100%",
      bg: "bg.emphasized",
      backgroundClip: "padding-box",
      borderWidth: "1px",
      backgroundImage: `url("data:image/svg+xml,%3Csvg width='6' height='6' viewBox='0 0 6 6' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='%239C92AC' fill-opacity='0.2' fill-rule='evenodd'%3E%3Cpath d='M5 0h1L0 6V5zM6 5v1H5z'/%3E%3C/g%3E%3C/svg%3E")`,
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
    }}
  />
)

"use client";

import { chakra } from "@chakra-ui/react"
import { DecorativeBox } from "@/components/rendyn-libraries/chakra/upstream/lib/decorative-box"

const Flex = chakra("div", {
  base: {
    display: "flex",
    gap: "4",
  },
  variants: {
    direction: {
      row: { flexDirection: "row" },
      column: { flexDirection: "column" },
    },
    align: {
      start: { alignItems: "flex-start" },
      center: { alignItems: "center" },
      end: { alignItems: "flex-end" },
    },
    justify: {
      start: { justifyContent: "flex-start" },
      center: { justifyContent: "center" },
      end: { justifyContent: "flex-end" },
    },
  },
})

export const SystemFlexRecipe = () => {
  return (
    <Flex direction="row" align="center" justify="center">
      <DecorativeBox height="10">Item 1</DecorativeBox>
      <DecorativeBox height="20">Item 2</DecorativeBox>
    </Flex>
  )
}

